                demand_of[depot] = 0
            else:
                depot = 0 if depot is None else depot
                customers = []
                demand_of = {depot: 0}
        else:
            n = len(demands)
            if depot is None:
                depot = 0
            customers = [i for i in range(n) if i != depot]
            demand_of = {i: demands[i] for i in range(n)}
            if depot not in demand_of:
                demand_of[depot] = 0

    if coords is not None:
        if isinstance(coords, dict):
            def coord_of(i):
                return coords[i]
        else:
            def coord_of(i):
                return coords[i]
    else:
        def coord_of(i):
            return (float(i), 0.0)

    def dist(a, b):
        pa = coord_of(a)
        pb = coord_of(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    def route_demand(route):
        s = 0
        for c in route:
            s += demand_of[c]
        return s

    def route_len(route):
        if not route:
            return 0.0
        total = dist(depot, route[0])
        for i in range(len(route) - 1):
            total += dist(route[i], route[i + 1])
        total += dist(route[-1], depot)
        return total

    unassigned = customers[:]
    routes = []

    while unassigned:
        seed = unassigned[0]
        best_key = (-dist(depot, seed), seed)
        for c in unassigned[1:]:
            key = (-dist(depot, c), c)
            if key > best_key:
                best_key = key
                seed = c

        route = [seed]
        load = demand_of[seed]
        unassigned.remove(seed)

        while True:
            best = None
            best_score = None
            last = route[-1]
            base_close = dist(last, depot)
            for c in unassigned:
                d = demand_of[c]
                if load + d > capacity:
                    continue
                score = dist(last, c) + dist(c, depot) - base_close
                key = (score, d, c)
                if best_score is None or key < best_score:
                    best_score = key
                    best = c
            if best is None:
                break
            route.append(best)
            load += demand_of[best]
            unassigned.remove(best)

        routes.append(route)

    improved = True
    while improved:
        improved = False
        for r_idx in range(len(routes)):
            r = routes[r_idx]
            n = len(r)
            if n < 4:
                continue
            changed = True
            while changed:
                changed = False
                for i in range(n - 2):
                    a = depot if i == 0 else r[i - 1]
                    b = r[i]
                    for j in range(i + 2, n):
                        c = r[j - 1]
                        d = depot if j == n else r[j]
                        old = dist(a, b) + dist(c, d)
                        new = dist(a, c) + dist(b, d)
                        if new + 1e-12 < old:
                            r[i:j] = r[i:j][::-1]
                            changed = True
                            improved = True
                            break
                    if changed:
                        break
            routes[r_idx] = r

    changed = True
    while changed:
        changed = False
        best_move = None
        best_gain = 0.0

        for i in range(len(routes)):
            ri = routes[i]
            li = route_demand(ri)
            for pos in range(len(ri)):
                c = ri[pos]
                dc = demand_of[c]
                prev_c = depot if pos == 0 else ri[pos - 1]
                next_c = depot if pos == len(ri) - 1 else ri[pos + 1]
                remove_cost = dist(prev_c, c) + dist(c, next_c) - dist(prev_c, next_c)

                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    lj = route_demand(rj)
                    if lj + dc > capacity:
                        continue
                    for ins in range(len(rj) + 1):
                        prev_j = depot if ins == 0 else rj[ins - 1]
                        next_j = depot if ins == len(rj) else rj[ins]
                        add_cost = dist(prev_j, c) + dist(c, next_j) - dist(prev_j, next_j)
                        gain = remove_cost - add_cost
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_move = ("relocate", i, pos, j, ins)

        if best_move is not None:
            _, i, pos, j, ins = best_move
            c = routes[i].pop(pos)
            if i == j and ins > pos:
                ins -= 1
            routes[j].insert(ins, c)
            if not routes[i]:
                routes.pop(i)
            changed = True
            continue

        best_swap = None
        best_gain = 0.0

        for i in range(len(routes)):
            ri = routes[i]
            li = route_demand(ri)
            for pos_i in range(len(ri)):
                a = ri[pos_i]
                da = demand_of[a]
                prev_a = depot if pos_i == 0 else ri[pos_i - 1]
                next_a = depot if pos_i == len(ri) - 1 else ri[pos_i + 1]
                remove_a = dist(prev_a, a) + dist(a, next_a) - dist(prev_a, next_a)

                for j in range(i + 1, len(routes)):
                    rj = routes[j]
                    lj = route_demand(rj)
                    for pos_j in range(len(rj)):
                        b = rj[pos_j]
                        db = demand_of[b]
                        if li - da + db > capacity or lj - db + da > capacity:
                            continue
                        prev_b = depot if pos_j == 0 else rj[pos_j - 1]
                        next_b = depot if pos_j == len(rj) - 1 else rj[pos_j + 1]
                        remove_b = dist(prev_b, b) + dist(b, next_b) - dist(prev_b, next_b)
                        add_a = dist(prev_b, a) + dist(a, next_b) - dist(prev_b, next_b)
                        add_b = dist(prev_a, b) + dist(b, next_a) - dist(prev_a, next_a)
                        gain = (remove_a + remove_b) - (add_a + add_b)
                        if gain > best_gain + 1e-12:
                            best_gain = gain
                            best_swap = (i, pos_i, j, pos_j)

        if best_swap is not None:
            i, pos_i, j, pos_j = best_swap
            routes[i][pos_i], routes[j][pos_j] = routes[j][pos_j], routes[i][pos_i]
            changed = True

    return routes
